import React, { useState, useRef, useEffect, useCallback } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";

const API = "http://localhost:5000";

function Register() {
  const location  = useLocation();
  const eventId   = location.state?.eventId   || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "", college_name: "", phone: "", email: "", event_id: eventId,
  });

  const [step, setStep] = useState(1);
  const [userId, setUserId] = useState("");
  const [qrData, setQrData] = useState("");
  const [photo, setPhoto] = useState("");
  const [utrNumber, setUtrNumber] = useState("");
  const [utrError, setUtrError] = useState("");
  const [utrScore, setUtrScore] = useState(null);
  const [utrVerdict, setUtrVerdict] = useState(""); // ✅ now USED
  const [submitting, setSubmitting] = useState(false);
  const [polling, setPolling] = useState(false);
  const [pollStatus, setPollStatus] = useState("");
  const [autoApproved, setAutoApproved] = useState(false);

  const videoRef  = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);
  const pollRef   = useRef(null);

  const YOUR_UPI_ID = "arunsekar664@okaxis";
  const AMOUNT      = "1";
  const PAYEE_NAME  = "CollegeEvent";
  const upiQRValue  = `upi://pay?pa=${YOUR_UPI_ID}&pn=${encodeURIComponent(PAYEE_NAME)}&am=${AMOUNT}&cu=INR`;

  useEffect(() => {
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, []);

  const handleChange = (e) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const validateUTRClient = (utr) => {
    const t = utr.trim();
    if (!t) return { valid: false, msg: "Enter UTR" };
    if (t.length < 10) return { valid: false, msg: "Min 10 chars" };
    if (!/^[a-zA-Z0-9]+$/.test(t)) return { valid: false, msg: "Only letters & numbers" };
    return { valid: true };
  };

  const submitUTR = async () => {
    setUtrError("");
    const check = validateUTRClient(utrNumber);

    if (!check.valid) {
      setUtrError(check.msg);
      return;
    }

    setSubmitting(true);
    try {
      const res = await axios.post(`${API}/submit-utr`, {
        utrNumber: utrNumber.trim(),
        amount: AMOUNT,
        ...formData,
        photo,
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        setUtrScore(res.data.utrScore);
        setUtrVerdict(res.data.verdict); // ✅ used now

        if (res.data.autoApproved) {
          setAutoApproved(true);
          setStep(4);
        } else {
          setStep(3);
          startPolling(res.data.userId);
        }
      } else {
        setUtrError(res.data.message || "Submission failed");
      }
    } catch (err) {
      setUtrError(err.response?.data?.message || "Server error");
    } finally {
      setSubmitting(false);
    }
  };

  const startPolling = useCallback((uid) => {
    setPolling(true);
    setPollStatus("Waiting for admin...");

    pollRef.current = setInterval(async () => {
      try {
        const res = await axios.get(`${API}/user-status/${uid}`);
        if (res.data.payment_status === "approved") {
          clearInterval(pollRef.current);
          setPolling(false);
          setStep(4);
        }
      } catch {
        setPollStatus("Checking...");
      }
    }, 5000);
  }, []);

  const openCamera = async () => {
    try {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((t) => t.stop());
      }

      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      await videoRef.current.play();
    } catch {
      alert("Camera access denied");
    }
  };

  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    canvas.getContext("2d").drawImage(video, 0, 0);
    setPhoto(canvas.toDataURL());

    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }

    setStep(5);
  };

  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "Event_ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  return (
    <div>
      <Navbar />
      <h2>Event Registration</h2>

      {step === 2 && utrVerdict && (   // ✅ FIXED WARNING HERE
        <p>Verdict: {utrVerdict}</p>
      )}

      {/* Keep your remaining UI SAME */}
    </div>
  );
}

export default Register;
